PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,login TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN('ADMIN','OPERADOR')),active INTEGER NOT NULL DEFAULT 1,failed_attempts INTEGER NOT NULL DEFAULT 0,locked_until TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS secretariats(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT,name TEXT NOT NULL UNIQUE,responsible TEXT,phone TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS units(id INTEGER PRIMARY KEY AUTOINCREMENT,secretariat_id INTEGER NOT NULL,name TEXT NOT NULL,address TEXT,responsible TEXT,phone TEXT,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(secretariat_id) REFERENCES secretariats(id));
CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY AUTOINCREMENT,unit_id INTEGER NOT NULL,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(unit_id) REFERENCES units(id));
CREATE TABLE IF NOT EXISTS teams(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,origin TEXT NOT NULL,responsible TEXT,notes TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS technicians(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,specialty TEXT,phone TEXT,team_id INTEGER,active INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(team_id) REFERENCES teams(id));
CREATE TABLE IF NOT EXISTS service_types(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS materials(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,unit TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS work_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,number INTEGER NOT NULL,opened_at TEXT NOT NULL,requester TEXT,requester_sector TEXT,requester_contact TEXT,request_origin TEXT,office_number TEXT,office_date TEXT,secretariat_id INTEGER NOT NULL,unit_id INTEGER NOT NULL,location_id INTEGER,service_type_id INTEGER NOT NULL,description TEXT NOT NULL,executed_service TEXT,priority TEXT NOT NULL DEFAULT 'MEDIA',deadline TEXT,estimated_amount REAL,estimated_unit TEXT CHECK(estimated_unit IN('HORAS','DIARIAS')),team_id INTEGER,workforce_origin TEXT,status TEXT NOT NULL DEFAULT 'ABERTA',progress INTEGER NOT NULL DEFAULT 10 CHECK(progress BETWEEN 0 AND 100),attended INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,final_note TEXT,attended_at TEXT,completed_at TEXT,cancel_reason TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(secretariat_id) REFERENCES secretariats(id),FOREIGN KEY(unit_id) REFERENCES units(id),FOREIGN KEY(location_id) REFERENCES locations(id),FOREIGN KEY(service_type_id) REFERENCES service_types(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS work_order_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,work_order_id INTEGER NOT NULL,note TEXT NOT NULL,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT,FOREIGN KEY(work_order_id) REFERENCES work_orders(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS work_order_labor(id INTEGER PRIMARY KEY AUTOINCREMENT,work_order_id INTEGER NOT NULL,technician_id INTEGER,team_id INTEGER,execution_date TEXT NOT NULL,start_time TEXT,end_time TEXT,daily_amount REAL,activity TEXT,created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(work_order_id) REFERENCES work_orders(id));
CREATE TABLE IF NOT EXISTS work_order_materials(id INTEGER PRIMARY KEY AUTOINCREMENT,work_order_id INTEGER NOT NULL,material_id INTEGER,description TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,situation TEXT NOT NULL CHECK(situation IN('NECESSARIO','PENDENTE','UTILIZADO')),created_by INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(work_order_id) REFERENCES work_orders(id));
CREATE TABLE IF NOT EXISTS work_order_attachments(id INTEGER PRIMARY KEY AUTOINCREMENT,work_order_id INTEGER NOT NULL,category TEXT NOT NULL,file_name TEXT NOT NULL,stored_path TEXT NOT NULL,mime_type TEXT,size_bytes INTEGER,description TEXT,uploaded_by INTEGER,uploaded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at TEXT,FOREIGN KEY(work_order_id) REFERENCES work_orders(id));
CREATE TABLE IF NOT EXISTS work_order_status_history(id INTEGER PRIMARY KEY AUTOINCREMENT,work_order_id INTEGER NOT NULL,previous_status TEXT,new_status TEXT NOT NULL,comment TEXT,changed_by INTEGER,changed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(work_order_id) REFERENCES work_orders(id));
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id INTEGER,before_json TEXT,after_json TEXT,machine TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS app_snapshots(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_work_orders_number ON work_orders(number);
CREATE INDEX IF NOT EXISTS idx_work_orders_status ON work_orders(status);
CREATE INDEX IF NOT EXISTS idx_work_orders_deadline ON work_orders(deadline);
CREATE INDEX IF NOT EXISTS idx_work_orders_secretariat ON work_orders(secretariat_id);
CREATE INDEX IF NOT EXISTS idx_work_orders_team ON work_orders(team_id);
